package com.autoops.command.controller;import com.autoops.command.retrieval.CommandRetrievalService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/commands")public class CommandSearchController{private final CommandRetrievalService service;public CommandSearchController(CommandRetrievalService s){service=s;}@GetMapping("/search")public CommandRetrievalService.Result search(@RequestParam String q){return service.search(q);}}
